    int x1, x2, y, f;
};

block b[20002];
int fie[10002][2];

bool comp(const block &b1, const block &b2) {
    return b1.y < b2.y;
}

void initArrays() {
    memset(fie, 0, sizeof(fie)); // Use memset to initialize the entire fie array to 0
    memset(b, 0, sizeof(b)); // Use memset to initialize the entire b array to 0
}

int main(void) {
    while (1) {
        scanf("%d%d", &n, &r);
        if (n == 0 && r == 0) break;

        initArrays();

        for (int i = 0; i < n; i++) {
