            b[i * 2 + 1].x1 = b[i * 2].x1;
            b[i * 2 + 1].x2 = b[i * 2].x2;
            b[i * 2].y = y1;
            b[i * 2 + 1].y = y2;
            b[i * 2].f = 1;
            b[i * 2 + 1].f = -1;
