                        cnt++;
                        if (bt == 0) cnt2++, bt = 1;
                    } else bt = 0;
                }
                res += cnt * (b[i].y - ny);
                res2 += cnt2 * 2 * (b[i].y - ny) + cnt3;
            }
            ny = b[i].y;
